async function loadLive(){if(user?.role!=="admin")return;try{const d=await request("/api/admin/live");const sessions=d.sessions||[];const examFilter=$("liveExamFilter"),oldFilter=examFilter.value||"all";examFilter.replaceChildren();const allExamsOption=document.createElement("option");allExamsOption.value="all";allExamsOption.textContent="All active tests";examFilter.append(allExamsOption);(d.exams||[]).filter(e=>e.status==="published").forEach(e=>{const o=document.createElement("option");o.value=e.id;o.textContent=(e.live_monitor_enabled?"📹 ":"") +e.title+(e.live_monitor_enabled?" · live enabled":" · monitoring off");examFilter.append(o)});examFilter.value=(d.exams||[]).some(e=>e.id===oldFilter)?oldFilter:"all";const selectedExam=examFilter.value;const visibleSessions=selectedExam==="all"?sessions:sessions.filter(x=>x.exam_id===selectedExam);$("liveSummary").replaceChildren();[["Active students",visibleSessions.length],["Live-enabled exams",(d.exams||[]).filter(e=>e.status==="published"&&e.live_monitor_enabled).length],["Refresh","4 sec"]].forEach(([label,value])=>{const el=document.createElement("div");el.className="metric";const b=document.createElement("b"),sp=document.createElement("span");b.textContent=value;sp.textContent=label;el.append(b,sp);$("liveSummary").append(el)});const target=$("adminCommTarget"),previous=target.value||"all";target.replaceChildren();const all=document.createElement("option");all.value="all";all.textContent="All participants in "+(selectedExam==="all"?"all tests":((d.exams||[]).find(e=>e.id===selectedExam)?.title||"selected test"))+" ("+visibleSessions.length+")";target.append(all);visibleSessions.forEach(s=>{const o=document.createElement("option");o.value=s.id;o.textContent=(s.full_name||s.email)+" · "+s.exam_title;target.append(o)});target.value=visibleSessions.some(x=>x.id===previous)?previous:"all";const examList=$("liveEnabledExams");if(examList){examList.replaceChildren();const liveExams=(d.exams||[]).filter(e=>e.status==="published"&&e.live_monitor_enabled);if(!liveExams.length){examList.textContent="No published exams currently have live monitoring enabled."}liveExams.forEach(e=>{const item=document.createElement("div");item.className="item";const left=document.createElement("div");left.className="left";const title=document.createElement("b"),desc=document.createElement("p");title.textContent=e.title;desc.textContent=e.active_count+" active student(s) · Live monitoring enabled"+(e.available_from?" · Starts "+new Date(e.available_from).toLocaleString():"")+(e.available_until?" · Ends "+new Date(e.available_until).toLocaleString():"");left.append(title,desc);item.append(left,makeButton("Open live room",()=>{$("liveExamFilter").value=e.id;loadLive()},"secondary"));examList.append(item)})}const list=$("liveSessions");list.replaceChildren();if(!visibleSessions.length){list.textContent="No students are taking a test right now in this filter."}visibleSessions.forEach(s=>{const item=document.createElement("div");item.className="item";const left=document.createElement("div");left.className="left";const title=document.createElement("b"),desc=document.createElement("p");title.textContent=(s.full_name||s.email)+" · "+s.exam_title;desc.textContent="Started "+s.started_at+" · Batch "+s.batch+" · "+s.event_count+" advisory events"+(s.latest_event?" · Last alert: "+s.latest_event:"");left.append(title,desc);const voiceCall=makeButton("Voice call",()=>startAdminCall(s.id,"voice"),"secondary"),videoCall=makeButton("Video call",()=>startAdminCall(s.id,"video"));if(!s.live_monitor_enabled){voiceCall.disabled=true;videoCall.disabled=true;voiceCall.title="Live monitoring is disabled for this exam";videoCall.title=voiceCall.title}desc.textContent+=" · Live monitor "+(s.live_monitor_enabled?"enabled":"disabled");item.append(left,makeButton("Message",()=>selectAdminChat(s.id),"secondary"),voiceCall,videoCall,makeButton("Terminate session",()=>terminateStudentSession(s),"danger"));list.append(item)});await loadAutomaticLiveStreams(sessions);if(target.value==="all"&&sessions.length===0){$("adminChatTranscript").replaceChildren();const p=document.createElement("p");p.className="muted";p.textContent="No active participants to message or call."; $("adminChatTranscript").append(p)}}catch(e){globalMessage(e.message,true)}}
async function loadAnalytics(){if(user?.role!=="admin")return;try{const d=await request("/api/admin/analytics");renderItems("subjectAnalytics",d.bySubject.map(x=>({title:x.subject,desc:x.accuracy+"% accuracy · "+x.correct+" correct · "+x.wrong+" wrong",tag:x.answers+" answers"})));renderItems("chapterAnalytics",d.byChapter.map(x=>({title:x.subject+" · "+(x.chapter||"Unspecified chapter"),desc:x.correct+" correct of "+x.answers+" answered",tag:x.answers+" answers"})));renderItems("scoreTrend",d.scoreTrend.map(x=>({title:x.day,desc:"Average score "+x.average_score,tag:x.attempts+" attempts"})))}catch(e){globalMessage(e.message,true)}}
async function loadStudentAnalysis(){try{const d=await request("/api/student/analysis"),rows=d.sessions.filter(s=>s.status==="submitted");$("studentAnalysisMetrics").replaceChildren();[["Tests submitted",rows.length],["Average score",rows.length?Math.round(rows.reduce((a,s)=>a+(s.score||0),0)/rows.length):"—"],["Latest score",rows.length?(rows[0].score??"—"):"—"]].forEach(([label,value])=>{const el=document.createElement("div");el.className="metric";const b=document.createElement("b"),sp=document.createElement("span");b.textContent=value;sp.textContent=label;el.append(b,sp);$("studentAnalysisMetrics").append(el)});renderItems("studentAnalysisList",d.sessions.map(s=>({title:s.exam_title,desc:s.status+" · "+s.started_at+(s.submitted_at?" · submitted "+s.submitted_at:""),tag:s.status==="submitted"?"Score "+(s.score??0):"In progress",kind:s.status==="submitted"?"green":"amber",action:s.status==="submitted"?makeButton("View report",()=>viewReport(s.id)) : null})));renderItems("studentRecent",rows.slice(0,4).map(s=>({title:s.exam_title,desc:s.submitted_at||s.started_at,tag:"Score "+(s.score??0),kind:"green"})))}catch(e){globalMessage(e.message,true)}}
async function loadProfile(){try{const d=await request("/api/account/profile"),p=d.profile;$("accountName").value=p.full_name||"";$("accountEmail").value=p.email;$("accountBatch").value=p.batch||"General";$("accountPhone").value=p.phone||"";$("accountGuardian").value=p.guardian_contact||"";$("accountCreated").value=p.created_at?new Date(p.created_at).toLocaleDateString():"";$("adminAccountEmail").textContent="Signed in as "+p.email}catch(e){globalMessage(e.message,true)}}
