async function exportCsv(){try{const r=await fetch(api+"/api/admin/reports/export.csv",{headers:{Authorization:"Bearer "+token}});const d=await r.clone().json().catch(()=>({}));if(!r.ok)throw new Error(d.error||"Export failed");const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="proctorguard-sessions.csv";a.click();URL.revokeObjectURL(url)}catch(e){globalMessage(e.message,true)}}
async function loadResults(){if(user?.role!=="admin")return;try{const d=await request("/api/admin/results"),all=d.results||[],filter=$("resultsFilter").value,rows=filter==="all"?all:all.filter(r=>r.status===filter);const summary=$("resultsSummary");summary.replaceChildren();[["All attempts",all.length],["Submitted",all.filter(r=>r.status==="submitted").length],["Active",all.filter(r=>r.status==="in_progress").length],["Terminated/expired",all.filter(r=>r.status==="expired").length]].forEach(([label,value])=>{const el=document.createElement("div");el.className="metric";const b=document.createElement("b"),span=document.createElement("span");b.textContent=value;span.textContent=label;el.append(b,span);summary.append(el)});const list=$("resultsList");list.replaceChildren();if(!rows.length){list.textContent="No attempts match this filter.";return}rows.forEach(r=>{const item=document.createElement("div");item.className="item";const left=document.createElement("div");left.className="left";const title=document.createElement("b"),desc=document.createElement("p"),time=document.createElement("p");title.textContent=(r.full_name||r.email)+" · "+r.exam_title;desc.textContent=r.status==="submitted"?"Score "+(r.score??"—")+" · Correct "+(r.correct_count??"—")+" · Wrong "+(r.wrong_count??"—")+" · Unattempted "+(r.unattempted_count??"—"):r.status==="expired"?(r.termination_reason?"Terminated by admin: "+r.termination_reason:"Expired or ended without a scored report"):"Attempt is currently active";time.textContent="Started "+new Date(r.started_at).toLocaleString()+(r.submitted_at?" · Ended "+new Date(r.submitted_at).toLocaleString():"");left.append(title,desc,time);item.append(left);const tag=document.createElement("span");tag.className="tag "+(r.status==="submitted"?"green":r.status==="in_progress"?"amber":"red");tag.textContent=r.status==="submitted"?"Scored":r.status==="in_progress"?"In progress":"Ended";item.append(tag);if(r.has_report)item.append(makeButton("View report",()=>viewReport(r.session_id),"secondary"));if(r.status==="in_progress")item.append(makeButton("Terminate",()=>terminateStudentSession({id:r.session_id,email:r.email,full_name:r.full_name,exam_title:r.exam_title}),"danger"));list.append(item)})}catch(e){globalMessage(e.message,true)}}
async function changeMyPassword(){const ids=user?.role==="admin"?{current:"currentPassword",next:"newPassword",confirm:"confirmNewPassword",status:"passwordChangeStatus"}:{current:"studentCurrentPassword",next:"studentNewPassword",confirm:"studentConfirmNewPassword",status:"studentPasswordChangeStatus"};const currentPassword=$(ids.current).value,newPassword=$(ids.next).value,confirmPassword=$(ids.confirm).value;if(newPassword.length<12){status(ids.status,"New password must be at least 12 characters.","bad");return}if(newPassword!==confirmPassword){status(ids.status,"New password and confirmation do not match.","bad");return}try{await request("/api/account/password",{method:"POST",body:JSON.stringify({currentPassword,newPassword})});[ids.current,ids.next,ids.confirm].forEach(id=>$(id).value="");status(ids.status,"Password changed successfully. Save it securely. Your current session can continue.","ok")}catch(e){status(ids.status,e.message,"bad")}}

function startExam(exam){pendingResume=null;pendingExam=exam;$("consentTitle").textContent="Camera, microphone & invigilation consent";$("consentModal").querySelector("p").textContent=exam.live_monitor_enabled?"This exam has live monitoring enabled. After you grant camera and microphone permission and agree below, your live camera feed will be available to the authorized administrator monitor during the test. The feed is not recorded by this app.":"This exam has live monitoring disabled. Your camera and microphone are used for local preview and advisory checks; audio/video is not sent to the administrator unless you join a live call.";["consentCamera","consentMic","consentLive"].forEach(id=>$(id).checked=false);status("consentStatus","All three consent boxes must be checked to start a proctored test.","");$("consentModal").classList.remove("hide")}
async function loadActiveSessionBanner(){if(user?.role!=="candidate")return;try{const d=await request("/api/student/active-session");activeSessionRecovery=d;if(!d.active){$("activeSessionBanner").classList.add("hide");return}$("activeSessionTitle").textContent=d.exam.title;$("activeSessionDetails").textContent=d.expired?"Your previous attempt has reached its time limit. Finalize it to calculate the saved answers.":(d.questions.length+" questions · "+Math.ceil(d.remainingSeconds/60)+" minutes remaining · "+d.savedAnswers.filter(a=>a.selectedIndex!==null).length+" answers saved.");$("resumeActiveTest").textContent=d.expired?"Finalize timed-out attempt":"Resume test";$("activeSessionBanner").classList.remove("hide");status("activeSessionStatus",d.expired?"The timer has expired. Finalizing will create the result from answers saved before time ran out.":"Your saved answers and original timer will be restored when you resume.","warn")}catch(e){status("activeSessionStatus",e.message,"bad")}}
async function resumeActiveTest(){try{if(!activeSessionRecovery?.active)await loadActiveSessionBanner();const d=activeSessionRecovery;if(!d?.active){status("activeSessionStatus","No active test session was found.","");return}if(d.expired){if(!confirm("The test time has expired. Finalize this attempt and calculate the result from saved answers?"))return;const result=await request("/api/sessions/"+d.session.id+"/submit",{method:"POST",body:"{}"});active=d;clearInterval(tick);stopSessionStatusPolling();$("portal").classList.add("hide");$("activeSessionBanner").classList.add("hide");currentReport=result.report;renderReport(result.report);$("reportView").classList.remove("hide");active=null;activeSessionRecovery=null;return}pendingResume=d;pendingExam=d.exam;$("consentTitle").textContent="Resume your active test";$("consentModal").querySelector("p").textContent="This test attempt is already in progress. Your saved answers will be restored and the original countdown will continue. Confirm camera, microphone and live-call consent for this browser session before resuming.";["consentCamera","consentMic","consentLive"].forEach(id=>$(id).checked=false);status("consentStatus","Check all three consent boxes to restore your existing test attempt.","");$("consentModal").classList.remove("hide")}catch(e){status("activeSessionStatus",e.message,"bad")}}
async function confirmExamConsent(){if(!pendingExam&&!pendingResume)return;if(!$("consentCamera").checked||!$("consentMic").checked||!$("consentLive").checked){status("consentStatus","Please check all three consent boxes before continuing.","bad");return}if(!navigator.mediaDevices?.getUserMedia){status("consentStatus","This browser does not support camera/microphone access. Open the test site in Safari or Chrome.","bad");return}const resumeData=pendingResume,exam=pendingExam;status("consentStatus","Requesting camera and microphone permission…","");try{camStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user",width:{ideal:640},height:{ideal:480}},audio:{echoCancellation:true,noiseSuppression:true}});examMediaConsent=true;const d=resumeData||await request("/api/exams/"+exam.id+"/sessions",{method:"POST",body:"{}"});active=d;const saved=new Map((d.savedAnswers||[]).map(a=>[a.questionId,a]));answers=d.questions.map(q=>saved.has(q.id)?saved.get(q.id).selectedIndex:null);marked=new Set();visitedQuestions=new Set();d.questions.forEach((q,i)=>{const a=saved.get(q.id);if(a&&(a.selectedIndex!==null||a.markedReview))visitedQuestions.add(i);if(a?.markedReview)marked.add(i)});questionIndex=answers.findIndex(a=>a===null);if(questionIndex<0)questionIndex=0;paletteFilter="All";deadline=Date.parse(d.session.startedAt)+d.session.durationMinutes*60000;$("consentModal").classList.add("hide");$("portal").classList.add("hide");$("activeSessionBanner").classList.add("hide");$("examView").classList.remove("hide");$("examView").classList.remove("previewHidden");$("hidePreview").textContent="Hide my preview";$("toggleExamMic").textContent="Mute microphone";$("toggleExamCamera").textContent="Turn camera off";renderExamQuestion();renderExamPalette();await startProctor();if(!resumeData)await sendEvent("monitoring_started","info","Student granted camera, microphone and live-call consent at test entry; face checks remain advisory.");startLiveSignalPolling();startStudentChatPolling();startSessionStatusPolling();tick=setInterval(()=>{const remain=Math.max(0,Math.ceil((deadline-Date.now())/1000));$("examTimer").textContent=String(Math.floor(remain/60)).padStart(2,"0")+":"+String(remain%60).padStart(2,"0");if(remain<=0){clearInterval(tick);submitExam(true)}},1000);pendingResume=null;pendingExam=null;activeSessionRecovery=null}catch(e){if(camStream){camStream.getTracks().forEach(t=>t.stop());camStream=null}examMediaConsent=false;status("consentStatus","Could not start/resume the test: "+e.message+". Check browser permissions and try again.","bad")}}
function cancelExamConsent(){$("consentModal").classList.add("hide");pendingExam=null;pendingResume=null;$("consentTitle").textContent="Camera, microphone & invigilation consent"}
function renderExamQuestion(){const q=active.questions[questionIndex];visitedQuestions.add(questionIndex);$("examSubject").textContent=q.subject.toUpperCase();$("examCounter").textContent="Question "+(questionIndex+1)+" of "+active.questions.length;$("examPrompt").textContent=q.prompt;$("examOptions").replaceChildren();q.options.forEach((o,i)=>{const label=document.createElement("label");label.className="option";const radio=document.createElement("input");radio.type="radio";radio.name="answer";radio.checked=answers[questionIndex]===i;const span=document.createElement("span");span.textContent=String.fromCharCode(65+i)+". "+o;radio.onchange=()=>saveAnswer(i);label.append(radio,span);$("examOptions").append(label)});$("examPrev").disabled=questionIndex===0;$("examNext").textContent=questionIndex===active.questions.length-1?"Last question →":"Save & next →";$("markReview").textContent=marked.has(questionIndex)?"★ Marked for review":"☆ Mark review"}
async function saveAnswer(value){answers[questionIndex]=value;status("saveState","Saving answer…");try{await request("/api/sessions/"+active.session.id+"/answers",{method:"PUT",body:JSON.stringify({questionId:active.questions[questionIndex].id,selectedIndex:value,markedReview:marked.has(questionIndex)})});status("saveState","Answer saved","ok");renderExamPalette()}catch(e){status("saveState","Save failed: "+e.message,"bad")}}
async function clearAnswer(){answers[questionIndex]=null;try{await request("/api/sessions/"+active.session.id+"/answers",{method:"PUT",body:JSON.stringify({questionId:active.questions[questionIndex].id,selectedIndex:null,markedReview:marked.has(questionIndex)})});renderExamQuestion();renderExamPalette();status("saveState","Answer cleared and saved","ok")}catch(e){status("saveState",e.message,"bad")}}
async function toggleReview(){if(marked.has(questionIndex))marked.delete(questionIndex);else marked.add(questionIndex);try{await request("/api/sessions/"+active.session.id+"/answers",{method:"PUT",body:JSON.stringify({questionId:active.questions[questionIndex].id,selectedIndex:answers[questionIndex],markedReview:marked.has(questionIndex)})});renderExamQuestion();renderExamPalette()}catch(e){globalMessage(e.message,true)}}
function renderExamPalette(){$("examPalette").replaceChildren();active.questions.forEach((q,i)=>{if(paletteFilter!=="All"&&q.subject!==paletteFilter)return;const b=document.createElement("button");b.textContent=i+1;let cls=answers[i]!==null?(marked.has(i)?"answered-review":"answered"):(marked.has(i)?"review":(visitedQuestions.has(i)?"not-answered":"not-visited"));b.className=cls+(i===questionIndex?" current":"");b.title="Q"+(i+1)+" · "+q.subject+" · "+(answers[i]!==null?(marked.has(i)?"Answered + review":"Answered"):(marked.has(i)?"Marked for review":(visitedQuestions.has(i)?"Not answered":"Not visited")));b.onclick=()=>goToQuestion(i);$("examPalette").append(b)});document.querySelectorAll("[data-subject-filter]").forEach(b=>{const selected=b.dataset.subjectFilter===paletteFilter;b.classList.toggle("secondary",!selected)})}
function goToQuestion(i){if(!active||i<0||i>=active.questions.length)return;questionIndex=i;if(paletteFilter!=="All"&&active.questions[i].subject!==paletteFilter)paletteFilter=active.questions[i].subject;renderExamQuestion();renderExamPalette()}
function waitForIce(pc,timeout=8000){if(pc.iceGatheringState==="complete")return Promise.resolve();return new Promise(resolve=>{let finished=false;const done=()=>{if(finished)return;finished=true;clearTimeout(timer);pc.removeEventListener("icegatheringstatechange",check);resolve()};const check=()=>{if(pc.iceGatheringState==="complete")done()};const timer=setTimeout(done,timeout);pc.addEventListener("icegatheringstatechange",check)})}
function startLiveSignalPolling(){if(livePollTimer)clearInterval(livePollTimer);livePollTimer=setInterval(pollLiveOffers,2500);pollLiveOffers()}
async function pollLiveOffers(){if(!active||user?.role!=="candidate"||!active.session?.id||pollingLiveOffers)return;pollingLiveOffers=true;try{const d=await request("/api/sessions/"+active.session.id+"/live-offers");for(const offer of (d.offers||[])){if(seenLiveOffers.has(offer.id))continue;seenLiveOffers.add(offer.id);if(!examMediaConsent){await declineLiveOffer(offer);continue}if(offer.mode==="monitor"){acceptLiveOffer(offer).catch(()=>{});continue}updateStudentCallBanner("Connecting to "+(offer.mode==="voice"?"an audio call":"a video call")+" with the administrator…");acceptLiveOffer(offer).catch(()=>{})}}catch{}finally{pollingLiveOffers=false}}
function updateStudentCallBanner(message){const bar=$("liveRequestBanner"),txt=$("liveRequestText"),actions=$("liveRequestActions");if(!bar||!txt||!actions)return;txt.textContent=message||("Live calls active: "+studentLivePeers.size+". You can mute your microphone, disable your camera, or end every live call.");actions.replaceChildren();actions.append(makeButton("Enable call audio",()=>{$("adminCallRemoteAudio")?.play().catch(()=>status("proctorStatus","Tap the page once, then enable call audio again.","warn"));$("adminCallRemoteVideo")?.play().catch(()=>{});},"secondary"),makeButton(camStream?.getAudioTracks().some(t=>t.enabled)?"Mute microphone":"Unmute microphone",toggleExamMic,"secondary"),makeButton(camStream?.getVideoTracks().some(t=>t.enabled)?"Turn camera off":"Turn camera on",toggleExamCamera,"secondary"),makeButton("End all live calls",endAllStudentCalls,"danger"));bar.classList.toggle("hide",studentLivePeers.size===0&&!message)}
async function declineLiveOffer(offer){try{await request("/api/sessions/"+active.session.id+"/live-offers/"+offer.id+"/answer",{method:"POST",body:JSON.stringify({declined:true})})}catch{}}
async function acceptLiveOffer(offer){
 const monitoring=offer.mode==="monitor";
 const sessionId=active?.session?.id;
 if(!active||!camStream||(monitoring?!camStream.getVideoTracks().some(t=>t.readyState==="live"):!camStream.getAudioTracks().some(t=>t.readyState==="live"))){
  if(!monitoring)status("proctorStatus","Microphone is unavailable for this call.","bad");
  await declineLiveOffer(offer);return;
 }
 let pc;
 try{
  if(monitoring){const previous=studentMonitorPeers.get(sessionId);if(previous){try{previous.close()}catch{}studentMonitorPeers.delete(sessionId)}}
  pc=new RTCPeerConnection(await getRtcConfiguration());
  pc.ontrack=ev=>{
   if(monitoring)return;
   const remote=ev.streams?.[0]||new MediaStream([ev.track]);
   const audio=$("adminCallRemoteAudio"),video=$("adminCallRemoteVideo");
   if(ev.track.kind==="audio"){audio.srcObject=remote;audio.play().catch(()=>{})}
   if(ev.track.kind==="video"&&offer.mode==="video"){video.srcObject=remote;video.style.display="block";video.play().catch(()=>{})}
  };
  await pc.setRemoteDescription({type:"offer",sdp:offer.offer_sdp});
  const tracks=monitoring?camStream.getVideoTracks():(offer.mode==="voice"?camStream.getAudioTracks():camStream.getTracks());
  tracks.filter(track=>track.readyState==="live").forEach(track=>pc.addTrack(track,camStream));
  if(monitoring)studentMonitorPeers.set(sessionId,pc);else studentLivePeers.set(offer.id,pc);
  pc.onconnectionstatechange=()=>{
   if(monitoring){
    if(studentMonitorPeers.get(sessionId)!==pc)return;
    if(pc.connectionState==="connected")status("proctorStatus","Live camera connected to administrator. Video only; microphone audio is not shared with the monitor.","ok");
    else if(["failed","closed"].includes(pc.connectionState)){studentMonitorPeers.delete(sessionId);try{pc.close()}catch{}}
   }else if(["failed","closed"].includes(pc.connectionState)){
    if(studentLivePeers.get(offer.id)===pc)studentLivePeers.delete(offer.id);
    try{pc.close()}catch{}
    if(active)updateStudentCallBanner();
   }
  };
  const answer=await pc.createAnswer();await pc.setLocalDescription(answer);await waitForIce(pc,10000);
  await request("/api/sessions/"+sessionId+"/live-offers/"+offer.id+"/answer",{method:"POST",body:JSON.stringify({answerSdp:pc.localDescription.sdp})});
  if(monitoring){status("proctorStatus","Your camera is being shared with the administrator monitor. Video only; no microphone audio is sent.","warn");return}
  status("proctorStatus",(offer.mode==="voice"?"Voice":"Video")+" call connected or connecting with administrator.","ok");
  updateStudentCallBanner();
 }catch(e){
  if(pc)try{pc.close()}catch{}
  if(monitoring){if(studentMonitorPeers.get(sessionId)===pc)studentMonitorPeers.delete(sessionId);status("proctorStatus","Camera monitor connection could not start: "+e.message+". The test can continue.","warn")}
  else{studentLivePeers.delete(offer.id);status("proctorStatus","Live call could not connect: "+e.message,"warn");await declineLiveOffer(offer);updateStudentCallBanner()}
 }
}
function toggleExamMic(){if(!camStream)return;const tracks=camStream.getAudioTracks(),enabled=tracks.some(t=>t.enabled);tracks.forEach(t=>t.enabled=!enabled);$("toggleExamMic").textContent=enabled?"Unmute microphone":"Mute microphone";updateStudentCallBanner()}
function toggleExamCamera(){if(!camStream)return;const tracks=camStream.getVideoTracks(),enabled=tracks.some(t=>t.enabled);tracks.forEach(t=>t.enabled=!enabled);$("toggleExamCamera").textContent=enabled?"Turn camera on":"Turn camera off";if(active)status("proctorStatus",enabled?"Camera turned off by you. You can turn it on again at any time.":"Camera enabled; advisory face checks may resume.","warn");updateStudentCallBanner()}
function togglePreview(){const exam=$("examView");const hidden=exam.classList.toggle("previewHidden");$("hidePreview").textContent=hidden?"Show my preview":"Hide my preview"}
function endAllStudentCalls(){for(const pc of studentLivePeers.values())try{pc.close()}catch{}studentLivePeers.clear();const audio=$("adminCallRemoteAudio"),video=$("adminCallRemoteVideo");if(audio)audio.srcObject=null;if(video){video.pause();video.srcObject=null;video.style.display="none"}updateStudentCallBanner();status("proctorStatus","You ended all live calls. Camera and microphone remain available for the test until you turn them off or submit.","warn")}
function endAutomaticAdminFeed(sessionId){const entry=autoLivePeers.get(sessionId);if(!entry)return;if(entry.answerTimer)clearInterval(entry.answerTimer);try{entry.pc?.close()}catch{}entry.card?.remove();autoLivePeers.delete(sessionId)}
async function startAutomaticAdminMonitor(session,entry){
 let pc;
 try{
  pc=new RTCPeerConnection(await getRtcConfiguration());
  if(autoLivePeers.get(session.id)!==entry){pc.close();return}
  entry.pc=pc;
  pc.addTransceiver("video",{direction:"recvonly"});
  pc.ontrack=ev=>{
   if(autoLivePeers.get(session.id)!==entry)return;
   entry.video.srcObject=ev.streams?.[0]||new MediaStream([ev.track]);
   entry.video.play().catch(()=>{});
   entry.state.textContent="Receiving student video · video only";
  };
  pc.onconnectionstatechange=()=>{
   if(autoLivePeers.get(session.id)!==entry||entry.pc!==pc)return;
   if(pc.connectionState==="connected"){entry.retryAfter=0;entry.state.textContent="Connected · live camera"}
   else if(["failed","disconnected"].includes(pc.connectionState)){entry.retryAfter=Date.now()+5000;entry.state.textContent="Connection interrupted · reconnecting automatically…"}
  };
  pc.oniceconnectionstatechange=()=>{
   if(autoLivePeers.get(session.id)!==entry||entry.pc!==pc)return;
   if(pc.iceConnectionState==="failed"){entry.retryAfter=Date.now()+5000;entry.state.textContent="Camera connection failed · retrying…"}
  };
  const offer=await pc.createOffer();
  await pc.setLocalDescription(offer);
  await waitForIce(pc,10000);
  if(autoLivePeers.get(session.id)!==entry||pc.connectionState==="closed")return;
  const created=await request("/api/admin/live/"+session.id+"/offers",{method:"POST",body:JSON.stringify({offerSdp:pc.localDescription.sdp,mode:"monitor"})});
  entry.offerId=created.offerId;
  entry.state.textContent="Waiting for student camera response…";
 }catch(e){
  if(autoLivePeers.get(session.id)===entry){
   entry.state.textContent="Could not start feed: "+e.message;
   entry.retryAfter=Date.now()+6000;
   if(pc)try{pc.close()}catch{}
   entry.pc=null;entry.offerId=null;
  }
 }
}
async function loadAutomaticLiveStreams(sessionsFromRefresh=[]){
 if(user?.role!=="admin"||!$("admin-live").classList.contains("active")||loadingAutomaticLiveStreams)return;
 loadingAutomaticLiveStreams=true;
 try{
  const examFilter=$("liveExamFilter")?.value||"all";
  const allSessions=Array.isArray(sessionsFromRefresh)?sessionsFromRefresh:[];
  const activeSessions=allSessions.filter(s=>s.live_monitor_enabled);
  const visible=activeSessions.filter(s=>examFilter==="all"||s.exam_id===examFilter);
  const capped=visible.slice(0,12),wanted=new Set(capped.map(s=>s.id));
  for(const id of [...autoLivePeers.keys()])if(!wanted.has(id))endAutomaticAdminFeed(id);
  const feeds=$("liveVideos"),empty=feeds.querySelector('[data-auto-empty="true"]');
  if(capped.length&&empty)empty.remove();
  if(!visible.length)status("autoLiveStatus",examFilter==="all"?"Waiting for a student to enter a live-enabled exam. Camera feeds start automatically after student consent.":"No active students with camera monitoring enabled for this exam.","");
  else if(visible.length>12)status("autoLiveStatus","Showing 12 of "+visible.length+" live feeds. Larger cohorts need a dedicated media server/SFU.","warn");
  else status("autoLiveStatus","Showing "+visible.length+" monitored student(s). Video only · not recorded.","ok");
  for(const session of capped){
   let entry=autoLivePeers.get(session.id);
   if(entry){
    entry.card.hidden=examFilter!=="all"&&entry.examId!==examFilter;
    if(entry.offerId&&session.monitor_offer_id===entry.offerId&&session.monitor_answer_sdp&&entry.pc&&!entry.pc.remoteDescription&&!entry.applyingAnswer){
     entry.applyingAnswer=true;
     entry.state.textContent="Student accepted · connecting video…";
     entry.pc.setRemoteDescription({type:"answer",sdp:session.monitor_answer_sdp}).then(()=>{
      if(autoLivePeers.get(session.id)===entry){entry.state.textContent="Answer received · establishing video…"}
     }).catch(e=>{
      if(autoLivePeers.get(session.id)===entry){entry.state.textContent="Answer failed: "+e.message;entry.retryAfter=Date.now()+5000}
     }).finally(()=>{entry.applyingAnswer=false});
    }else if(entry.offerId&&session.monitor_offer_id===entry.offerId&&session.monitor_offer_status==="declined"){
     entry.state.textContent="Student camera unavailable. Will retry shortly.";
     entry.retryAfter=Math.max(entry.retryAfter||0,Date.now()+12000);
    }
    if(entry.pc&&["connected","connecting","new"].includes(entry.pc.connectionState))continue;
    if(entry.retryAfter&&Date.now()<entry.retryAfter)continue;
    endAutomaticAdminFeed(session.id);
   }
   const card=document.createElement("div");card.className="videoCard";card.dataset.autoSession=session.id;
   const title=document.createElement("b");title.textContent=(session.full_name||session.email)+" · "+session.exam_title;
   const state=document.createElement("p");state.textContent="Starting secure video connection…";
   const video=document.createElement("video");video.autoplay=true;video.playsInline=true;video.muted=true;video.setAttribute("aria-label","Live camera feed for "+(session.full_name||session.email));video.className="live-student-video";
   const meta=document.createElement("div");meta.className="videoMeta";meta.textContent=(session.batch||"General")+" · Video only";
   card.append(title,state,video,meta);feeds.append(card);
   entry={pc:null,card,video,state,examId:session.exam_id,offerId:null,retryAfter:0,applyingAnswer:false};
   autoLivePeers.set(session.id,entry);
   startAutomaticAdminMonitor(session,entry);
  }
  if(!feeds.querySelector(".videoCard")){if(!feeds.querySelector('[data-auto-empty="true"]')){const p=document.createElement("p");p.dataset.autoEmpty="true";p.className="muted";p.textContent="No live camera feeds yet.";feeds.append(p)}}
 }catch(e){status("autoLiveStatus","Could not refresh live camera feeds: "+e.message,"bad")}
 finally{loadingAutomaticLiveStreams=false}
}
async function ensureAdminCallMedia(mode){if(!adminAudioStream||!adminAudioStream.getAudioTracks().some(t=>t.readyState==="live"))adminAudioStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});if(mode==="video"&&(!adminVideoStream||!adminVideoStream.getVideoTracks().some(t=>t.readyState==="live")))adminVideoStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:"user",width:{ideal:640},height:{ideal:480}}});if(mode==="video"){const wrap=$("adminCameraPreviewWrap"),preview=$("adminCameraPreview");if(wrap&&preview&&adminVideoStream){preview.srcObject=adminVideoStream;wrap.classList.remove("hide");preview.play().catch(()=>{})}}const tracks=[...adminAudioStream.getAudioTracks(),...(mode==="video"?adminVideoStream.getVideoTracks():[])];return new MediaStream(tracks)}
function stopAdminMediaIfIdle(){if(adminLivePeers.size)return;if(adminAudioStream){adminAudioStream.getTracks().forEach(t=>t.stop());adminAudioStream=null}if(adminVideoStream){adminVideoStream.getTracks().forEach(t=>t.stop());adminVideoStream=null}const wrap=$("adminCameraPreviewWrap"),preview=$("adminCameraPreview");if(wrap)wrap.classList.add("hide");if(preview){preview.pause();preview.srcObject=null}}
function endAdminCall(sessionId){const entry=adminLivePeers.get(sessionId);if(entry){try{entry.pc.close()}catch{}entry.card?.remove();adminLivePeers.delete(sessionId)}else document.querySelector('#callVideos [data-session="'+sessionId+'"]')?.remove();stopAdminMediaIfIdle();if(!$("callVideos").querySelector(".videoCard")){if(!$("callVideos").children.length||!$("callVideos").querySelector("p.muted")){const p=document.createElement("p");p.className="muted";p.textContent="No live calls active.";$("callVideos").replaceChildren(p)}}}
function endAllAdminCalls(){[...adminLivePeers.keys()].forEach(endAdminCall);status("adminCommStatus","All calls ended.","ok")}
async function startAdminCall(target,mode){if(!window.RTCPeerConnection){status("adminCommStatus","This browser does not support WebRTC calls.","bad");return}try{const d=await request("/api/admin/live"),sessions=d.sessions||[],selected=target||$("adminCommTarget").value,examFilter=$("liveExamFilter").value;$("adminCommTarget").value=selected;let recipients=selected==="all"?(examFilter==="all"?sessions:sessions.filter(x=>x.exam_id===examFilter)):sessions.filter(x=>x.id===selected);if(selected==="all")recipients=recipients.filter(x=>Boolean(x.live_monitor_enabled));else if(recipients[0]&&!recipients[0].live_monitor_enabled)throw new Error("Live audio/video is disabled for this exam. You can still message the student.");if(!recipients.length)throw new Error("No active live-monitor-enabled test session matches that recipient.");if(selected==="all"&&recipients.length>12)throw new Error("This free peer-to-peer prototype can call up to 12 active test sessions at once. Large group calls need a media relay/SFU service.");const stream=await ensureAdminCallMedia(mode);const results=await Promise.all(recipients.map(session=>startAdminCallForSession(session,mode,stream)));const ok=results.filter(Boolean).length;status("adminCommStatus",(mode==="voice"?"Voice":"Video")+" call started for "+ok+" of "+recipients.length+" selected active session(s). Each student sees a call indicator and can end calls.","ok")}catch(e){status("adminCommStatus",e.message,"bad")}}
async function startAdminCallForSession(session,mode,stream){if(adminLivePeers.has(session.id)){return false}const feeds=$("callVideos");const empty=feeds.querySelector("p.muted");if(empty)feeds.replaceChildren();const card=document.createElement("div");card.className="videoCard";card.dataset.session=session.id;const title=document.createElement("b");title.textContent=(session.full_name||session.email)+" · "+(mode==="voice"?"Voice call":"Video call");const state=document.createElement("p");state.textContent="Sending call invitation…";const video=document.createElement("video");video.autoplay=true;video.playsInline=true;video.muted=true;video.style.cssText="width:100%;max-height:230px;background:#17243b;border-radius:10px;"+(mode==="video"?"":"display:none");const audio=document.createElement("audio");audio.autoplay=true;audio.playsInline=true;audio.style.cssText=mode==="voice"?"width:100%":"display:none";const close=makeButton("End call",()=>endAdminCall(session.id),"danger");card.append(title,state,video,audio,close);feeds.append(card);let pc,offerId;try{pc=new RTCPeerConnection(await getRtcConfiguration());adminLivePeers.set(session.id,{pc,card,video,audio,state,mode});stream.getTracks().forEach(track=>pc.addTrack(track,stream));pc.ontrack=ev=>{const remote=ev.streams?.[0]||new MediaStream([ev.track]);audio.srcObject=remote;audio.play().catch(()=>{});if(mode==="video"){video.srcObject=remote;video.play().catch(()=>{})}state.textContent="Connected · not recorded by ProctorGuard"};pc.onconnectionstatechange=()=>{if(["failed","disconnected"].includes(pc.connectionState))state.textContent="Connection lost or blocked by network. Try again or check network compatibility.";if(pc.connectionState==="connected")state.textContent="Connected · "+(mode==="voice"?"audio":"audio/video")+" active"};const offer=await pc.createOffer();await pc.setLocalDescription(offer);await waitForIce(pc);const created=await request("/api/admin/live/"+session.id+"/offers",{method:"POST",body:JSON.stringify({offerSdp:pc.localDescription.sdp,mode})});offerId=created.offerId;state.textContent="Call sent · waiting for student connection…";for(let i=0;i<25;i++){await new Promise(r=>setTimeout(r,1000));if(pc.connectionState==="closed")return false;const result=await request("/api/admin/live/"+session.id+"/offers/"+offerId+"/answer");if(result.offer.status==="declined"){state.textContent="Call was declined.";pc.close();adminLivePeers.delete(session.id);stopAdminMediaIfIdle();return false}if(result.offer.answer_sdp){await pc.setRemoteDescription({type:"answer",sdp:result.offer.answer_sdp});state.textContent="Answer received · connecting…";return true}}state.textContent="No answer yet. Confirm the student is still in their test and has consented.";pc.close();adminLivePeers.delete(session.id);stopAdminMediaIfIdle();return false}catch(e){state.textContent="Call unavailable: "+e.message;if(pc)pc.close();adminLivePeers.delete(session.id);stopAdminMediaIfIdle();return false}}
async function terminateStudentSession(session){const label=(session.full_name||session.email)+" · "+session.exam_title;if(!confirm("Terminate the active test session for "+label+"? The student will be removed from the test. Answers saved so far will be retained, but no final score/report will be generated."))return;const reason=prompt("Reason for termination (optional):","Terminated by administrator");if(reason===null)return;try{const d=await request("/api/admin/sessions/"+session.id+"/terminate",{method:"POST",body:JSON.stringify({reason:reason.trim()||"Terminated by administrator"})});status("adminCommStatus","Session terminated. The student has been notified; saved answers were retained.","ok");endAdminCall(session.id);await loadLive();await loadDashboard()}catch(e){status("adminCommStatus",e.message,"bad")}}
