async function startProctor(){try{if(!camStream)throw new Error("Camera/microphone consent is not available.");$("proctorVideo").srcObject=camStream;$("proctorPill").textContent="Camera & mic ready";$("proctorStatus").textContent="Loading face detector…";if(!window.faceapi)throw new Error("Face detector library did not load");await faceapi.nets.ssdMobilenetv1.loadFromUri("https://justadudewhohacks.github.io/face-api.js/models/");faceModelReady=true;$("proctorStatus").className="status ok";$("proctorStatus").textContent="Face detector ready. Processing stays in this tab; live calls begin only when the administrator starts one.";proctorTimer=setInterval(checkProctor,2500)}catch(e){faceModelReady=false;$("proctorPill").textContent="Media consented";$("proctorStatus").className="status warn";$("proctorStatus").textContent="Camera/mic are available, but the advisory face detector could not start: "+e.message;await sendEvent("camera_interrupted","medium","Face detector could not start: "+String(e.message||e).slice(0,300))}}
async function checkProctor(){if(!active||!faceModelReady||proctorBusy)return;proctorBusy=true;try{const v=$("proctorVideo");if(camStream?.getVideoTracks().length&&camStream.getVideoTracks().every(t=>!t.enabled)){$("proctorStatus").className="status warn";$("proctorStatus").textContent="Camera is off by your choice; face-presence checks are paused.";return}if(!camStream||camStream.getVideoTracks().every(t=>t.readyState!=="live")){if(Date.now()-(alertTimes.camera||0)>20000){alertTimes.camera=Date.now();await sendEvent("camera_interrupted","medium","Camera stream is no longer active")}$("proctorStatus").className="status bad";$("proctorStatus").textContent="Camera interrupted";return}if(!v.videoWidth)return;const faces=await faceapi.detectAllFaces(v,new faceapi.SsdMobilenetv1Options({minConfidence:.55}));if(!faces.length){absenceFrames++;multiFrames=0;$("proctorStatus").className="status warn";$("proctorStatus").textContent="No face detected · please centre your face";if(absenceFrames>=3&&Date.now()-(alertTimes.absent||0)>20000){alertTimes.absent=Date.now();await sendEvent("face_absent","medium","No face detected across repeated checks")}}else if(faces.length>1){multiFrames++;absenceFrames=0;$("proctorStatus").className="status warn";$("proctorStatus").textContent="Multiple faces detected ("+faces.length+")";if(multiFrames>=2&&Date.now()-(alertTimes.multi||0)>20000){alertTimes.multi=Date.now();await sendEvent("multiple_faces","medium","More than one face detected in repeated checks")}}else{absenceFrames=0;multiFrames=0;$("proctorStatus").className="status ok";$("proctorStatus").textContent="One face detected · presence signal only"}}catch(e){$("proctorStatus").className="status warn";$("proctorStatus").textContent="Face analysis temporarily unavailable"}finally{proctorBusy=false}}
function stopProctor(){if(proctorTimer)clearInterval(proctorTimer);proctorTimer=null;if(camStream){camStream.getTracks().forEach(t=>t.stop());camStream=null}faceModelReady=false}
function stopSessionStatusPolling(){if(sessionStatusTimer)clearInterval(sessionStatusTimer);sessionStatusTimer=null}
function startSessionStatusPolling(){stopSessionStatusPolling();sessionStatusTimer=setInterval(pollSessionStatus,3000);pollSessionStatus()}
async function pollSessionStatus(){if(!active||user?.role!=="candidate")return;try{const d=await request("/api/sessions/"+active.session.id+"/status");if(d.status!=="in_progress"){finishEndedSession(d)}}catch(e){/* transient network errors should not interrupt an exam */}}
function finishEndedSession(d){stopSessionStatusPolling();if(tick)clearInterval(tick);tick=null;stopProctor();stopLiveSignals();active=null;examMediaConsent=false;$("examView").classList.add("hide");$("reportView").classList.add("hide");$("portal").classList.add("hide");$("sessionEndedTitle").textContent=d.terminatedByAdmin?"Session terminated by administrator":"Test session has ended";$("sessionEndedMessage").textContent=d.terminatedByAdmin?"The administrator ended your test session."+ (d.terminationReason?" Reason: "+d.terminationReason:""):"This test session is no longer active. Any answers saved before it ended have been retained."; $("sessionEndedView").classList.remove("hide")}
async function sendEvent(eventType,severity="low",detail=""){if(!active)return;try{await request("/api/sessions/"+active.session.id+"/events",{method:"POST",body:JSON.stringify({eventType,severity,detail})})}catch{}}
async function submitExam(auto=false){if(!active)return;if(!auto&&!confirm("Submit the exam? You cannot change answers after submission."))return;try{const d=await request("/api/sessions/"+active.session.id+"/submit",{method:"POST",body:"{}"});clearInterval(tick);stopSessionStatusPolling();stopProctor();stopLiveSignals();currentReport=d.report;renderReport(d.report);$("examView").classList.add("hide");$("reportView").classList.remove("hide")}catch(e){globalMessage(e.message,true)}}
async function viewReport(id){try{const d=await request("/api/reports/"+id);currentReport=d.report;renderReport(d.report);$("portal").classList.add("hide");$("reportView").classList.remove("hide")}catch(e){globalMessage(e.message,true)}}
function renderReport(r){$("reportTitle").textContent="Score: "+r.score+" / "+r.maxScore;$("reportMetrics").replaceChildren();[["Correct",r.correct],["Incorrect",r.wrong],["Unattempted",r.unattempted],["Accuracy",r.accuracy+"%"]].forEach(([k,v])=>{const d=document.createElement("div");d.className="metric";const b=document.createElement("b"),s=document.createElement("span");b.textContent=v;s.textContent=k;d.append(b,s);$("reportMetrics").append(d)});renderItems("reportSubjects",Object.entries(r.subjectBreakdown).map(([s,x])=>({title:s,desc:x.correct+" correct · "+x.wrong+" wrong · "+x.unattempted+" unattempted",tag:x.score+" points"})));renderItems("reportAnswers",r.answers.map(a=>({title:"Q"+a.number+" · "+a.subject+" · "+(a.isCorrect?"Correct":a.selectedIndex===null?"Unattempted":"Incorrect"),desc:a.prompt+" | Your answer: "+(a.selectedAnswer??"—")+" | Correct: "+a.correctAnswer+" | "+a.explanation,tag:a.markedReview?"Review":"Done"})))}
async function backToPortal(){if(active&&tick)clearInterval(tick);stopSessionStatusPolling();active=null;stopProctor();stopLiveSignals();$("reportView").classList.add("hide");$("examView").classList.add("hide");$("sessionEndedView").classList.add("hide");$("portal").classList.remove("hide");if(user?.role==="admin")showPage("admin-home");else{showPage("student-analysis");loadStudentAnalysis()}}
function logout(){if(active&&tick){if(!confirm("An exam is active. Leaving may interrupt your session. Sign out anyway?"))return;stopProctor();stopLiveSignals();clearInterval(tick)}token="";user=null;active=null;if(liveRefreshTimer)clearInterval(liveRefreshTimer);$("portal").classList.add("hide");$("examView").classList.add("hide");$("reportView").classList.add("hide");$("authArea").classList.remove("hide");$("config").classList.remove("hide");$("login").classList.add("hide");$("logout").classList.add("hide");$("userPill").classList.add("hide");$("email").value="";$("password").value=""}
$("connect").onclick=connect;$("loginBtn").onclick=login;$("logout").onclick=logout;$("confirmConsent").onclick=confirmExamConsent;$("cancelConsent").onclick=cancelExamConsent;$("hidePreview").onclick=togglePreview;$("toggleExamMic").onclick=toggleExamMic;$("toggleExamCamera").onclick=toggleExamCamera;$("sendStudentMessage").onclick=sendStudentMessage;$("studentChatInput").addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();sendStudentMessage()}});$("returnAfterTermination").onclick=()=>{stopSessionStatusPolling();$("sessionEndedView").classList.add("hide");$("portal").classList.remove("hide");showPage("student-home");loadExams();loadStudentAnalysis();loadActiveSessionBanner();};$("resumeActiveTest").onclick=resumeActiveTest;$("refreshActiveSession").onclick=loadActiveSessionBanner;$("sendAdminMessage").onclick=sendAdminMessage;$("adminMessageInput").addEventListener("keydown",e=>{if(e.key==="Enter"&&(e.metaKey||e.ctrlKey)){e.preventDefault();sendAdminMessage()}});$("adminCommTarget").onchange=loadAdminChat;$("liveExamFilter").onchange=()=>{loadLive();loadAdminChat()};$("refreshAdminChat").onclick=loadAdminChat;$("adminVoiceCall").onclick=()=>startAdminCall($("adminCommTarget").value,"voice");$("adminVideoCall").onclick=()=>startAdminCall($("adminCommTarget").value,"video");$("stopAllCalls").onclick=endAllAdminCalls;$("draftExam").onchange=()=>{clearQuestionEditor();loadDraftSettingsFromExam($("draftExam").value);loadQuestionList()};$("saveDraftSettings").onclick=saveDraftSettings;$("saveQuestion").onclick=saveQuestion;$("cancelQuestionEdit").onclick=()=>{clearQuestionEditor();loadQuestionList()};$("refreshResults").onclick=loadResults;$("exportResultsCsv").onclick=exportCsv;$("resultsFilter").onchange=loadResults;$("changeMyPassword").onclick=changeMyPassword;$("studentChangePassword").onclick=changeMyPassword;$("createCandidate").onclick=createCandidate;$("createExam").onclick=createExam;$("importBank").onclick=importBank;$("publishExam").onclick=publishExam;$("reloadDrafts").onclick=()=>loadDrafts();$("refreshExams").onclick=loadExams;$("refreshAdminExams").onclick=loadExams;$("refreshStudents").onclick=loadStudents;$("studentSearch").addEventListener("input",renderStudentDirectory);$("exportStudentsCsv").onclick=exportStudentsCsv;$("refreshFees").onclick=loadFees;$("refreshLive").onclick=loadLive;$("liveExamFilter").onchange=()=>{loadLive();loadAdminChat()};$("refreshAnalytics").onclick=loadAnalytics;$("refreshStudentVideos").onclick=()=>loadVideos(false);$("refreshAdminVideos").onclick=()=>loadVideos(true);$("addVideo").onclick=addVideo;$("saveAccount").onclick=saveAccount;$("exportCsv").onclick=exportCsv;$("exportCsv2").onclick=exportCsv;$("closePreview").onclick=()=>$("previewModal").classList.add("hide");$("backToExams").onclick=backToPortal;$("exitExam").onclick=()=>submitExam(false);$("examPrev").onclick=()=>{if(questionIndex>0)goToQuestion(questionIndex-1)};$("examNext").onclick=()=>{if(questionIndex<active.questions.length-1)goToQuestion(questionIndex+1)};document.querySelectorAll("[data-subject-filter]").forEach(b=>b.onclick=()=>{paletteFilter=b.dataset.subjectFilter;renderExamPalette()});$("markReview").onclick=toggleReview;$("clearAnswer").onclick=clearAnswer;$("submitExam").onclick=()=>submitExam(false);$("downloadReport").onclick=()=>{if(!currentReport)return;const blob=new Blob([JSON.stringify(currentReport,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="proctorguard-report-"+currentReport.sessionId+".json";a.click();URL.revokeObjectURL(url)};
document.querySelectorAll(".nav button[data-page]").forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.querySelectorAll("[data-goto]").forEach(b=>b.onclick=()=>showPage(b.dataset.goto));document.addEventListener("visibilitychange",()=>{if(document.hidden&&active)sendEvent("tab_hidden","medium","Browser tab became inactive; may have legitimate causes.")});window.addEventListener("beforeunload",e=>{if(active&&!$("reportView").classList.contains("hide"))return;if(active){e.preventDefault();e.returnValue=""}});
$("demoHelp").onclick=()=>globalMessage("V3 stores app code in GitHub. To preserve student records across free-host restarts, configure encrypted snapshots to a separate private GitHub data repository. Never put passwords, tokens or unencrypted student data into the code repository.",false);
window.addEventListener("DOMContentLoaded",()=>{$("apiOrigin").value=window.location.origin;connect()});
